window.SMD_AUDIO_CASES = [{"id":"new-001","code":"A01","title":"Spacecraft cabin","prompt":"integrated_multimodal_description: [Shot 1] A 20mm lens glides slowly through a wide range of a spacecraft cabin as an astronaut gently pushes off a wall. Tools, droplets, and loose paper drift and rotate around the body while the camera weaves between them, arcs from floor level to ceiling level, and inspects the same microgravity event from a second angle without a cut. The portrait frame uses the cabin's full vertical depth to preserve body, ceiling, floor, and floating objects in one five-second shot.\noverall_soundscape: Suit breathing, muted cabin ventilation, light tool taps, droplets striking surfaces, paper flutter, and a soft wall push-off thump.\nnon_diegetic_music: Sparse suspended synth with slow, weightless harmonic movement.","width":768,"height":1344,"steps":{"4":{"ours":{"src":"assets/h3-selected-20261001/new-001-4-ours.mp4","poster":"assets/h3-selected-20261001/new-001-4-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-001-4-baseline.mp4","poster":"assets/h3-selected-20261001/new-001-4-baseline-poster.webp"}},"8":{"ours":{"src":"assets/h3-selected-20261001/new-001-8-ours.mp4","poster":"assets/h3-selected-20261001/new-001-8-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-001-8-baseline.mp4","poster":"assets/h3-selected-20261001/new-001-8-baseline-poster.webp"}}}},{"id":"t2va-h3doc-015","code":"A02","title":"Anime youth","prompt":"integrated_multimodal_description: [Shot 1] Clean expressive Japanese 2D school anime with fine stable line art, crisp cel shading, and a detailed hand-painted classroom background. After school, one short-haired teenage girl sits alone at a window-side desk in a white short-sleeve shirt and navy school skirt. No other student is present. An open notebook, textbook with colored bookmark, pencil case, drink carton, canvas school bag, wooden desks, pale curtain, partial blackboard, noticeboard, green treetops, and the opposite school building fill the frame. Warm golden sunlight illuminates her cheek and casts window-frame shadows across the desks. She looks down at the notebook, then lifts one hand and slowly brushes a loose strand of hair behind her ear, turning her face toward the window with a small private smile. Her hand, fingers, face, and hair remain cleanly drawn. The camera makes a gentle slow push toward her as the curtain moves in the breeze, then holds on her expression.\noverall_soundscape: Quiet empty classroom, distant sports field, one soft curtain rustle, fabric movement, and a pencil rolling a short distance.\nnon_diegetic_music: A gentle original piano melody with no vocals.","width":900,"height":514,"steps":{"4":{"ours":{"src":"assets/feature-overviews/t2va-h3doc-015-ours-4.mp4","poster":"assets/feature-overviews/t2va-h3doc-015-ours-4-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3doc-015-dmd-4.mp4","poster":"assets/feature-overviews/t2va-h3doc-015-dmd-4-poster.webp"}},"8":{"ours":{"src":"assets/feature-overviews/t2va-h3doc-015-ours-8.mp4","poster":"assets/feature-overviews/t2va-h3doc-015-ours-8-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3doc-015-dmd-8.mp4","poster":"assets/feature-overviews/t2va-h3doc-015-dmd-8-poster.webp"}}}},{"id":"new-004","code":"A03","title":"Dinosaur in the rain","prompt":"integrated_multimodal_description: [Shot 1] A 40mm lens tracks slowly backward over a short range on a flooded road. A lone watcher stands beside a stalled vehicle as a colossal tyrant dinosaur steps from rain-dark foliage and lowers its head toward the lens. Lightning reveals the full silhouette for one breath, then the animal roars; the camera retreats only a few meters, keeping the circular head, reflective asphalt, and black tree wall centered in the square frame.\noverall_soundscape: Rain rattles metal, water runs through the road gutters, the vehicle clicks, and the roar rolls across the trees.\nnon_diegetic_music: Sparse sub-bass and bowed glass, with silence immediately before the roar.","width":1024,"height":1024,"steps":{"4":{"ours":{"src":"assets/h3-selected-20261001/new-004-4-ours.mp4","poster":"assets/h3-selected-20261001/new-004-4-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-004-4-baseline.mp4","poster":"assets/h3-selected-20261001/new-004-4-baseline-poster.webp"}},"8":{"ours":{"src":"assets/h3-selected-20261001/new-004-8-ours.mp4","poster":"assets/h3-selected-20261001/new-004-8-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-004-8-baseline.mp4","poster":"assets/h3-selected-20261001/new-004-8-baseline-poster.webp"}}}},{"id":"t2va-h3doc-016","code":"A04","title":"Animal interaction","prompt":"integrated_multimodal_description: [Shot 1] Realistic close bird photography of two affectionate cockatiels standing side by side on the same natural wooden perch. The left bird has a gray body, yellow face, orange cheek patch, and clear crest; the right bird has a cream-white body, pale yellow head, orange cheek patch, and clear crest. Both colors and positions remain unchanged. At the start, the left bird lowers its head with eyes partly closed while the right bird gently preens the base of its crest with small precise beak movements. The right bird then withdraws and lowers its own head; without changing places, the left bird slowly raises its head and gently preens the right bird's crest. Only one bird moves actively at a time. Bodies, folded wings, feet, perch, and long tails remain stable. Warm window light reveals soft feathers and eye highlights; mossy wood, edge leaves, a small ceramic food dish, warm wooden bird furniture, and defocused plants fill the frame. Fixed bird-eye-level close camera.\noverall_soundscape: Soft feather movement, tiny beak contacts, quiet bird breaths, faint room ambience, and an occasional gentle chirp.\nnon_diegetic_music: No music.","width":900,"height":514,"steps":{"4":{"ours":{"src":"assets/feature-overviews/t2va-h3doc-016-ours-4.mp4","poster":"assets/feature-overviews/t2va-h3doc-016-ours-4-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3doc-016-dmd-4.mp4","poster":"assets/feature-overviews/t2va-h3doc-016-dmd-4-poster.webp"}},"8":{"ours":{"src":"assets/feature-overviews/t2va-h3doc-016-ours-8.mp4","poster":"assets/feature-overviews/t2va-h3doc-016-ours-8-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3doc-016-dmd-8.mp4","poster":"assets/feature-overviews/t2va-h3doc-016-dmd-8-poster.webp"}}}},{"id":"new-006","code":"A05","title":"Kitchen materials","prompt":"integrated_multimodal_description: [Shot 1] With a 24mm lens, the camera tracks 9 meters at measured speed around a marble island. Warm pools slide across dark cabinetry, brushed metal, and veined stone; the camera’s moderate pace lets each reflection resolve before the next. The composition stacks island, pendants, and ceiling height as one quiet study of domestic materials, with no people entering the frame.\noverall_soundscape: Refrigeration hums, a pendant chain ticks faintly, ventilation breathes, and polished stone carries a soft room resonance.\nnon_diegetic_music: Minimal piano, rubbed vibraphone, and bass clarinet trace the changing reflections.","width":768,"height":1344,"steps":{"4":{"ours":{"src":"assets/h3-selected-20261001/new-006-4-ours.mp4","poster":"assets/h3-selected-20261001/new-006-4-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-006-4-baseline.mp4","poster":"assets/h3-selected-20261001/new-006-4-baseline-poster.webp"}},"8":{"ours":{"src":"assets/h3-selected-20261001/new-006-8-ours.mp4","poster":"assets/h3-selected-20261001/new-006-8-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-006-8-baseline.mp4","poster":"assets/h3-selected-20261001/new-006-8-baseline-poster.webp"}}}},{"id":"t2va-h3doc-018","code":"A06","title":"Fantasy scale hatching","prompt":"integrated_multimodal_description: [Shot 1] An epic realistic fantasy scene inside a volcanic crater. A building-sized obsidian egg sits embedded in black lava rock while one complete young dragon is curled inside. One upper shell plate remains attached at its back edge; the dragon has dark charcoal wet-looking scales, two short horns, a thick muzzle, amber eyes in normal sockets, folded wings, and one sturdy paw on the shell edge. A tiny explorer in a rust-red coat stands on the lower-left rock ridge for scale. From a fixed low camera, the dragon forcefully lifts its head and pushes the shell plate upward with its horns, exposing its face, shoulder, and folded wing. It then opens its mouth and releases one short powerful cone of orange fire upward across the dark crater, lighting the shell, scales, and nearby rock with a sudden warm glow. The explorer flinches one step backward but remains on the ridge. The dragon stays inside the egg and folds its head back slightly after the flame; the shell remains mostly intact.\noverall_soundscape: Rigid shell scraping, falling grit, a young dragon inhale, one forceful fire burst, flames roaring briefly, and volcanic wind.\nnon_diegetic_music: A low choral rise followed by one strong orchestral hit during the fire burst.","width":900,"height":514,"steps":{"4":{"ours":{"src":"assets/feature-overviews/t2va-h3doc-018-ours-4.mp4","poster":"assets/feature-overviews/t2va-h3doc-018-ours-4-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3doc-018-dmd-4.mp4","poster":"assets/feature-overviews/t2va-h3doc-018-dmd-4-poster.webp"}},"8":{"ours":{"src":"assets/feature-overviews/t2va-h3doc-018-ours-8.mp4","poster":"assets/feature-overviews/t2va-h3doc-018-ours-8-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3doc-018-dmd-8.mp4","poster":"assets/feature-overviews/t2va-h3doc-018-dmd-8-poster.webp"}}}},{"id":"new-008","code":"A07","title":"Kayaking over a waterfall","prompt":"integrated_multimodal_description: [Shot 1] A wide daylight view establishes a rugged waterfall surrounded by wet rock, dense green foliage, and churning white water as a bright pink kayak approaches the lip. [Shot 2] At 00:01.500, cut to the kayaker's POV camera tracking at rapid speed through a moderate waterfall descent: the paddle plants on alternating sides, the bow reaches the edge, and the kayak drops into the foaming pool below. Spray fills the foreground as the kayak levels out and continues into the fast downstream rapids, with direct, energetic documentary motion.\noverall_soundscape: Constant roaring water, forceful paddle splashes, wind rush, the hull striking turbulent water, and spray striking the kayak.\nnon_diegetic_music: N/A","width":1344,"height":768,"steps":{"4":{"ours":{"src":"assets/h3-selected-20261001/new-008-4-ours.mp4","poster":"assets/h3-selected-20261001/new-008-4-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-008-4-baseline.mp4","poster":"assets/h3-selected-20261001/new-008-4-baseline-poster.webp"}},"8":{"ours":{"src":"assets/h3-selected-20261001/new-008-8-ours.mp4","poster":"assets/h3-selected-20261001/new-008-8-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-008-8-baseline.mp4","poster":"assets/h3-selected-20261001/new-008-8-baseline-poster.webp"}}}},{"id":"t2va-h3wave01-l05","code":"A08","title":"Fantasy fire bird","prompt":"integrated_multimodal_description: [Shot 1] A snow-covered mountain temple roof at early dawn, with dark curved tiles, heavy white snow, bronze ridge ornaments, cedar trees, and distant peaks filling a cold blue landscape. One large phoenix with a coherent eagle-like body, two broad wings, a long layered tail, and restrained ember-red and gold feathers descends directly toward the central roof ridge. The full bird is visible from the first frame against the pale sky. It performs two slow powerful wingbeats, extends both feet, and lands heavily on the snowy ridge. The landing lifts one controlled curtain of powder snow. Warm heat from its planted feet melts a clear circular halo through the snow to the dark tiles while the phoenix folds both wings and raises its head into a proud final pose. The camera retreats smoothly just above roof height to keep the full descent and temple silhouette readable. No additional birds, firestorm, or exploding roof; feather count and anatomy remain coherent.\noverall_soundscape: Cold mountain wind, two heavy wingbeats, talons on tile, snow lifting and hissing as it melts, feathers settling, and one clear phoenix cry.\nnon_diegetic_music: Broad horns and low drums resolving into a warm sustained chord at the landing pose.","width":900,"height":514,"steps":{"4":{"ours":{"src":"assets/feature-overviews/t2va-h3wave01-l05-ours-4.mp4","poster":"assets/feature-overviews/t2va-h3wave01-l05-ours-4-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave01-l05-dmd-4.mp4","poster":"assets/feature-overviews/t2va-h3wave01-l05-dmd-4-poster.webp"}},"8":{"ours":{"src":"assets/feature-overviews/t2va-h3wave01-l05-ours-8.mp4","poster":"assets/feature-overviews/t2va-h3wave01-l05-ours-8-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave01-l05-dmd-8.mp4","poster":"assets/feature-overviews/t2va-h3wave01-l05-dmd-8-poster.webp"}}}},{"id":"new-009","code":"A09","title":"Fresh bread","prompt":"integrated_multimodal_description: [Shot 1] In a brightly and evenly lit professional bakery, a baker wearing a pink uniform and red headscarf slides a wooden peel beneath two golden-brown loaves inside a large industrial oven. From a steady medium view, the camera pans slightly at steady speed over a short work-area range as the baker draws the peel straight outward, bringing both loaves fully through the oven opening. Keep the extraction centered and continuous, ending with the loaves supported on the peel just outside the oven while work surfaces and bakery equipment remain softly visible behind them in straightforward documentary realism.\noverall_soundscape: The wooden peel scraping lightly against the oven surface, low ventilation and kitchen room tone, a soft shift of clothing, and subtle metal resonance from the industrial oven.\nnon_diegetic_music: N/A","width":1344,"height":768,"steps":{"4":{"ours":{"src":"assets/h3-selected-20261001/new-009-4-ours.mp4","poster":"assets/h3-selected-20261001/new-009-4-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-009-4-baseline.mp4","poster":"assets/h3-selected-20261001/new-009-4-baseline-poster.webp"}},"8":{"ours":{"src":"assets/h3-selected-20261001/new-009-8-ours.mp4","poster":"assets/h3-selected-20261001/new-009-8-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-009-8-baseline.mp4","poster":"assets/h3-selected-20261001/new-009-8-baseline-poster.webp"}}}},{"id":"t2va-h3wave01-l07","code":"A10","title":"Macro glass creature","prompt":"integrated_multimodal_description: [Shot 1] Extreme macro photography of one transparent glass scarab resting on an antique topographic map beside a brass compass at sunrise. The scarab is already fully readable in the first frame: clear curved shell, small gold joints, six dark glass legs, precise antennae, and subtle internal refraction. Warm window light crosses the paper fibers, ink contours, compass rim, and scattered grains of sand. The scarab raises its shell covers, unfolds exactly two thin prismatic flight wings, and beats them slowly enough to remain visible. It lifts several centimeters above the map and holds in a stable hover. As the wings open, one band of rainbow light sweeps across the map and compass, providing the payoff without changing the insect's material. The macro camera pulls back and tilts up slightly to keep the complete beetle and colored shadow in view. No swarm, no transformation, and no extra wings.\noverall_soundscape: Quiet room tone, tiny glass feet releasing from paper, delicate wing vibration, a faint crystal chime, and compass metal settling.\nnon_diegetic_music: A single bright harp glissando timed to the prismatic shadow.","width":900,"height":514,"steps":{"4":{"ours":{"src":"assets/feature-overviews/t2va-h3wave01-l07-ours-4.mp4","poster":"assets/feature-overviews/t2va-h3wave01-l07-ours-4-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave01-l07-dmd-4.mp4","poster":"assets/feature-overviews/t2va-h3wave01-l07-dmd-4-poster.webp"}},"8":{"ours":{"src":"assets/feature-overviews/t2va-h3wave01-l07-ours-8.mp4","poster":"assets/feature-overviews/t2va-h3wave01-l07-ours-8-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave01-l07-dmd-8.mp4","poster":"assets/feature-overviews/t2va-h3wave01-l07-dmd-8-poster.webp"}}}},{"id":"new-011","code":"A11","title":"Manta ray","prompt":"integrated_multimodal_description: [Shot 1] In clear blue water above a colorful coral reef, a manta ray glides forward with its broad pectoral fins moving in slow, fluid strokes. From one continuous low-side medium-wide viewpoint, the camera tracks horizontally beside and slightly below the ray at slow speed across a moderate reef distance, keeping its underside patterns and the coral below visible in the same composition. Maintain this single tracking angle as the manta ray passes over the reef and continues forward. Sunlight filters evenly through the water, revealing natural color and texture without changing the camera height or shot scale.\noverall_soundscape: Soft, muffled underwater ambience, the gentle rush of water around the ray's fins, and a faint current moving across the reef.\nnon_diegetic_music: N/A","width":1344,"height":768,"steps":{"4":{"ours":{"src":"assets/h3-selected-20261001/new-011-4-ours.mp4","poster":"assets/h3-selected-20261001/new-011-4-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-011-4-baseline.mp4","poster":"assets/h3-selected-20261001/new-011-4-baseline-poster.webp"}},"8":{"ours":{"src":"assets/h3-selected-20261001/new-011-8-ours.mp4","poster":"assets/h3-selected-20261001/new-011-8-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-011-8-baseline.mp4","poster":"assets/h3-selected-20261001/new-011-8-baseline-poster.webp"}}}},{"id":"t2va-h3wave01-l08","code":"A12","title":"Surreal forest portal","prompt":"integrated_multimodal_description: [Shot 1] In a dark mossy forest after rain, one freestanding weathered blue wooden door stands upright between old beech trees. A woman in a long rust-red coat faces the door from three steps away, seen in side profile. Ferns, roots, wet bark, blue fog, fallen leaves, and small pools fill the frame; a thin line of warm sunlight already leaks around the closed door. She approaches, grasps the simple brass handle, and opens the door outward in one continuous motion. Inside the rectangular frame is a bright sunlit ocean cliff with moving blue water and white surf, while the space beside and behind the door remains the same dark forest. Ocean wind pushes through the opening, lifting her coat edge, hair, and nearby ferns. She takes one cautious step toward the threshold and stops. The camera arcs smoothly around her and the door so the final frame proves that the ocean exists only within the doorway. Door geometry, forest, and ocean boundary remain stable; no water floods out.\noverall_soundscape: Wet forest ambience, handle and hinge, ocean surf appearing as the door opens, wind through leaves and coat fabric, and one cautious footstep.\nnon_diegetic_music: Low strings in the forest opening into a bright distant choir at the ocean reveal.","width":900,"height":514,"steps":{"4":{"ours":{"src":"assets/feature-overviews/t2va-h3wave01-l08-ours-4.mp4","poster":"assets/feature-overviews/t2va-h3wave01-l08-ours-4-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave01-l08-dmd-4.mp4","poster":"assets/feature-overviews/t2va-h3wave01-l08-dmd-4-poster.webp"}},"8":{"ours":{"src":"assets/feature-overviews/t2va-h3wave01-l08-ours-8.mp4","poster":"assets/feature-overviews/t2va-h3wave01-l08-ours-8-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave01-l08-dmd-8.mp4","poster":"assets/feature-overviews/t2va-h3wave01-l08-dmd-8-poster.webp"}}}},{"id":"new-014","code":"A13","title":"Macaw taking flight","prompt":"integrated_multimodal_description: [Shot 1] In a dense green forest, a red macaw perches on a branch extending from a large weathered tree trunk. Begin with a stable medium-long documentary view as patches of sunlight filter through the canopy and pick out the bird's vivid feathers against shaded foliage. [Shot 2] At 00:03.500, the macaw spreads its wings, launches from the branch, and flies through the open space between trees. The camera tracks at steady speed through a moderate gap between trees, following its fluid path and fully extended colorful wings while maintaining the layered forest background and natural play of light and shadow.\noverall_soundscape: Light forest wind, leaves stirring, claws releasing from bark, strong wingbeats, and branches rustling as the bird passes.\nnon_diegetic_music: N/A","width":1344,"height":768,"steps":{"4":{"ours":{"src":"assets/h3-selected-20261001/new-014-4-ours.mp4","poster":"assets/h3-selected-20261001/new-014-4-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-014-4-baseline.mp4","poster":"assets/h3-selected-20261001/new-014-4-baseline-poster.webp"}},"8":{"ours":{"src":"assets/h3-selected-20261001/new-014-8-ours.mp4","poster":"assets/h3-selected-20261001/new-014-8-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-014-8-baseline.mp4","poster":"assets/h3-selected-20261001/new-014-8-baseline-poster.webp"}}}},{"id":"t2va-h3wave01-p03","code":"A14","title":"Portrait macro animal","prompt":"integrated_multimodal_description: [Shot 1] A 9:16 vertical realistic macro scene on a warm breakfast table. Three oversized porcelain teacups are stacked securely in a staggered tower, each with a large handle forming a clear climbing route. One small brown field mouse with stable anatomy, round ears, bright eyes, and a long thin tail begins on the lower saucer holding one white sugar cube between its front paws. Floral cup patterns, tea stains, a silver spoon, linen fibers, crumbs, sliced orange, and morning window light fill the portrait composition. The mouse climbs the first handle, crosses the middle saucer, and climbs the final handle while keeping the sugar cube. The camera follows upward at mouse height with shallow but sufficient depth of field. At the top cup, the mouse pushes the cube over the rim; it falls into the tea and creates one small crown-shaped splash. The mouse sits beside the rim and looks down at the result. Cup count, stack geometry, mouse identity, and route remain stable.\noverall_soundscape: Morning kitchen room tone, tiny claws on porcelain, mouse breaths, sugar scraping, one soft tea splash, and spoon resonance.\nnon_diegetic_music: Playful pizzicato strings with a tiny bell note at the splash.","width":768,"height":1344,"steps":{"4":{"ours":{"src":"assets/feature-overviews/t2va-h3wave01-p03-ours-4.mp4","poster":"assets/feature-overviews/t2va-h3wave01-p03-ours-4-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave01-p03-dmd-4.mp4","poster":"assets/feature-overviews/t2va-h3wave01-p03-dmd-4-poster.webp"}},"8":{"ours":{"src":"assets/feature-overviews/t2va-h3wave01-p03-ours-8.mp4","poster":"assets/feature-overviews/t2va-h3wave01-p03-ours-8-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave01-p03-dmd-8.mp4","poster":"assets/feature-overviews/t2va-h3wave01-p03-dmd-8-poster.webp"}}}},{"id":"new-016","code":"A15","title":"Mountain rally","prompt":"integrated_multimodal_description: [Shot 1] In bright sun, an aerial camera tracks quickly over a broad distance above a rally car racing along a narrow mountain road beside steep cliffs and rocky outcrops, the pavement winding like a thin ribbon over the canyon. [Shot 2] At 00:03.000, a fixed interior camera shows the driver's hands making precise steering inputs through a sharp turn as sunlight and shadows flick across the cabin. [Shot 3] At 00:05.500, a ground-level camera makes a brisk, wide pan as the car climbs past and continues around the exposed bend.\noverall_soundscape: High engine revs, tire noise on pavement, and wind around the mountain road.\nnon_diegetic_music: N/A","width":1344,"height":768,"steps":{"4":{"ours":{"src":"assets/h3-selected-20261001/new-016-4-ours.mp4","poster":"assets/h3-selected-20261001/new-016-4-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-016-4-baseline.mp4","poster":"assets/h3-selected-20261001/new-016-4-baseline-poster.webp"}},"8":{"ours":{"src":"assets/curated-20260930/H8-082-ours.mp4","poster":"assets/h3-selected-20261001/new-016-8-ours-poster.webp"},"baseline":{"src":"assets/curated-20260930/H8-082-dmd.mp4","poster":"assets/h3-selected-20261001/new-016-8-baseline-poster.webp"}}}},{"id":"t2va-h3wave02-l04","code":"A16","title":"Cinematic craft","prompt":"integrated_multimodal_description: [Shot 1] A lone blacksmith works on an open basalt forge platform above a glowing volcanic valley at night. The blacksmith wears a heavy dark leather apron, face shield, and gloves and already holds one straight white-hot sword with long tongs above a rectangular stone quench trough. An anvil, coal forge, tool rack, black rock, orange lava seams, and distant smoke layers fill the wide frame. In one direct controlled motion, the blacksmith plunges the complete blade vertically into the dark water. A dense column of white steam erupts upward, illuminated orange from below, while the trough sends one circular wave across its surface. The camera performs a short push toward the impact and stops with the blacksmith, tongs, blade hilt, and steam column clearly separated. No hammering sequence, flying sword, fire creature, or extra worker.\noverall_soundscape: Volcanic rumble, forge roar, metal entering water, one violent hiss, trough water slapping stone, leather movement, and tongs resonating.\nnon_diegetic_music: One low drum impact followed by a short brass swell under the steam.","width":900,"height":514,"steps":{"4":{"ours":{"src":"assets/feature-overviews/t2va-h3wave02-l04-ours-4.mp4","poster":"assets/feature-overviews/t2va-h3wave02-l04-ours-4-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave02-l04-dmd-4.mp4","poster":"assets/feature-overviews/t2va-h3wave02-l04-dmd-4-poster.webp"}},"8":{"ours":{"src":"assets/feature-overviews/t2va-h3wave02-l04-ours-8.mp4","poster":"assets/feature-overviews/t2va-h3wave02-l04-ours-8-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave02-l04-dmd-8.mp4","poster":"assets/feature-overviews/t2va-h3wave02-l04-dmd-8-poster.webp"}}}},{"id":"new-018","code":"A17","title":"Autumn train journey","prompt":"integrated_multimodal_description: [Shot 1] From inside a moving train car, a stable camera looks through the window as the train follows a curved railway through a mountainous autumn forest. Tall evergreens mix with deciduous trees carrying yellow and orange leaves; rocky outcrops and patches of grass pass beside the track. Warm sunlight filters between trunks, moving shadows across the ground. The camera makes a gentle, slight pan to keep the curve of the train and passing foliage within the frame.\noverall_soundscape: Rhythmic rail noise, low carriage vibration, and soft wind around the moving train.\nnon_diegetic_music: N/A","width":1344,"height":768,"steps":{"4":{"ours":{"src":"assets/h3-selected-20261001/new-018-4-ours.mp4","poster":"assets/h3-selected-20261001/new-018-4-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-018-4-baseline.mp4","poster":"assets/h3-selected-20261001/new-018-4-baseline-poster.webp"}},"8":{"ours":{"src":"assets/h3-selected-20261001/new-018-8-ours.mp4","poster":"assets/h3-selected-20261001/new-018-8-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-018-8-baseline.mp4","poster":"assets/h3-selected-20261001/new-018-8-baseline-poster.webp"}}}},{"id":"t2va-h3wave02-l08","code":"A18","title":"Tidal macro fantasy","prompt":"integrated_multimodal_description: [Shot 1] Night macro photography of one large rough oyster resting in a shallow tidal pool between black rocks. Moonlight, clear ripples, green seaweed, tiny barnacles, wet shell ridges, and the reflected full moon fill the first frame. The oyster slowly opens its two shell halves, revealing one smooth white pearl nested inside. The pearl catches the moon reflection, then rises several centimeters above the shell inside a thin coherent column of water, remaining perfectly spherical and solid. The camera pulls back slightly along the water surface so the floating pearl, open oyster, and real moon reflection align in one composition. Surrounding rocks and seaweed stay fixed; no extra pearls, tentacles, or magical particle cloud.\noverall_soundscape: Small night waves, shell creak, water draining from the opening, a low liquid lift, seaweed movement, and distant surf.\nnon_diegetic_music: One soft glassy tone rising and holding with the pearl.","width":900,"height":514,"steps":{"4":{"ours":{"src":"assets/feature-overviews/t2va-h3wave02-l08-ours-4.mp4","poster":"assets/feature-overviews/t2va-h3wave02-l08-ours-4-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave02-l08-dmd-4.mp4","poster":"assets/feature-overviews/t2va-h3wave02-l08-dmd-4-poster.webp"}},"8":{"ours":{"src":"assets/feature-overviews/t2va-h3wave02-l08-ours-8.mp4","poster":"assets/feature-overviews/t2va-h3wave02-l08-ours-8-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave02-l08-dmd-8.mp4","poster":"assets/feature-overviews/t2va-h3wave02-l08-dmd-8-poster.webp"}}}},{"id":"new-022","code":"A19","title":"Cavalry at dawn","prompt":"integrated_multimodal_description: [Shot 1] A rider sits within a long cavalry line at cinematic dawn, horses and riders forming a broad moving texture while two nearest riders remain the principal subjects. A tripod-locked camera remains still in a wide 1344x768 frame as spears rise and hooves begin a slow walk. The formation gathers into a controlled trot across the bright field, expanding toward the skyline without leaving the composition. Warm light catches tack and mane while the background line advances as scale texture. The unmoving viewpoint turns the collective advance into one sustained stability study.\noverall_soundscape: Layered hoofbeats, leather tack, breath from nearby horses, wind across grass, and distant metal creaks.\nnon_diegetic_music: None.","width":1344,"height":768,"steps":{"4":{"ours":{"src":"assets/h3-selected-20261001/new-022-4-ours.mp4","poster":"assets/h3-selected-20261001/new-022-4-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-022-4-baseline.mp4","poster":"assets/h3-selected-20261001/new-022-4-baseline-poster.webp"}},"8":{"ours":{"src":"assets/h3-selected-20261001/new-022-8-ours.mp4","poster":"assets/h3-selected-20261001/new-022-8-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-022-8-baseline.mp4","poster":"assets/h3-selected-20261001/new-022-8-baseline-poster.webp"}}}},{"id":"t2va-h3wave02-l09","code":"A20","title":"Playful animal motion","prompt":"integrated_multimodal_description: [Shot 1] A rain-fresh bamboo forest with one young red panda sitting upright on a broad red maple leaf floating in a shallow clear stream. The panda, leaf, striped tail, mossy stones, bamboo stalks, ferns, small waterfall, and amber leaves are visible in the opening frame. The current catches the leaf and carries it along one smooth curved channel between stones. The red panda lowers its body, grips the leaf edges with both front paws, and leans naturally through the bend while its tail trails above the water. The leaf glides over a short gentle cascade and lands on a calm pool, rocking once before settling beside a mossy bank. The camera follows at water level, moving beside and slightly ahead of the panda to preserve its face and the route. No second animal, violent rapids, spinning, or leaf tearing.\noverall_soundscape: Clear stream, leaf sliding on water, a small cascade, bamboo rain drops, soft paws on leaf, and one red-panda chirp.\nnon_diegetic_music: Light marimba and woodwind notes following the curved ride.","width":900,"height":514,"steps":{"4":{"ours":{"src":"assets/feature-overviews/t2va-h3wave02-l09-ours-4.mp4","poster":"assets/feature-overviews/t2va-h3wave02-l09-ours-4-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave02-l09-dmd-4.mp4","poster":"assets/feature-overviews/t2va-h3wave02-l09-dmd-4-poster.webp"}},"8":{"ours":{"src":"assets/feature-overviews/t2va-h3wave02-l09-ours-8.mp4","poster":"assets/feature-overviews/t2va-h3wave02-l09-ours-8-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave02-l09-dmd-8.mp4","poster":"assets/feature-overviews/t2va-h3wave02-l09-dmd-8-poster.webp"}}}},{"id":"new-023","code":"A21","title":"Robot launch","prompt":"integrated_multimodal_description: [Shot 1] A giant robot rises from a launch cradle beside an evacuated harbor at blue hour. A tripod-locked camera stays still, framing the robot, magnetic rails, and quiet blocks beyond in one 1344x768 composition. Vapor spills from the joints as the cradle releases; the machine travels forward above the first avenue and raises one arm toward a bright disturbance over the water. It stops before contact, leaving the poised deployment, harbor lights, and suspended machine as a single sustained event.\noverall_soundscape: Hydraulic hiss, magnetic rail vibration, harbor wind, distant warning beacons, and heavy joint servos.\nnon_diegetic_music: A restrained electronic pulse that widens at release.","width":1344,"height":768,"steps":{"4":{"ours":{"src":"assets/h3-selected-20261001/new-023-4-ours.mp4","poster":"assets/h3-selected-20261001/new-023-4-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-023-4-baseline.mp4","poster":"assets/h3-selected-20261001/new-023-4-baseline-poster.webp"}},"8":{"ours":{"src":"assets/h3-selected-20261001/new-023-8-ours.mp4","poster":"assets/h3-selected-20261001/new-023-8-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-023-8-baseline.mp4","poster":"assets/h3-selected-20261001/new-023-8-baseline-poster.webp"}}}},{"id":"t2va-h3wave02-l10","code":"A22","title":"Fantasy vehicle scale","prompt":"integrated_multimodal_description: [Shot 1] One weathered wooden three-mast sailing ship moves across the surface of a dense white cloud sea between enormous dark mountain peaks at sunrise. The ship is already visible bow-first in the opening frame, with complete hull, three masts, cream sails, rigging, and no visible crew. The cloud layer behaves like slow water beneath the hull while remaining vapor at its edges. The ship advances steadily, its bow parting one soft wake through the clouds. Wind fills the sails and the vessel turns gradually to broadside as it passes a near mountain pinnacle. The camera begins low beside the bow above the cloud surface, travels backward along the hull, then pulls far out to reveal the complete ship, mountain corridor, orange horizon, and long cloud wake. Masts, sails, and rigging stay coherent; no flying ship lift-off, storm, or fleet.\noverall_soundscape: High-altitude wind, wooden hull creaks, ropes and sails, a deep cloud-sea rush, and distant mountain echoes.\nnon_diegetic_music: Expansive strings and horns opening gradually with the broadside reveal.","width":900,"height":514,"steps":{"4":{"ours":{"src":"assets/feature-overviews/t2va-h3wave02-l10-ours-4.mp4","poster":"assets/feature-overviews/t2va-h3wave02-l10-ours-4-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave02-l10-dmd-4.mp4","poster":"assets/feature-overviews/t2va-h3wave02-l10-dmd-4-poster.webp"}},"8":{"ours":{"src":"assets/feature-overviews/t2va-h3wave02-l10-ours-8.mp4","poster":"assets/feature-overviews/t2va-h3wave02-l10-ours-8-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave02-l10-dmd-8.mp4","poster":"assets/feature-overviews/t2va-h3wave02-l10-dmd-8-poster.webp"}}}},{"id":"new-035","code":"A23","title":"Night race","prompt":"integrated_multimodal_description: [Shot 1] The locked-off camera uses a 24mm lens in a steady, short-range cockpit shot. First-person cockpit view during a wet night race. Spray from cars ahead veils the track as the driver makes rapid steering corrections, brakes late into a corner, passes one car on the inside, briefly loses traction, catches the slide, and accelerates into a tunnel. The camera uses a 24mm lens in a steady, short-range locked cockpit shot fixed behind the wheel, with road reflections and wiper-cleared glimpses marking each maneuver.\noverall_soundscape: Engine pitch, tire spray, wiper swishes, brake squeal, gear changes, rain on the windshield, and tunnel echo.\nnon_diegetic_music: None.","width":1344,"height":768,"steps":{"4":{"ours":{"src":"assets/h3-selected-20261001/new-035-4-ours.mp4","poster":"assets/h3-selected-20261001/new-035-4-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-035-4-baseline.mp4","poster":"assets/h3-selected-20261001/new-035-4-baseline-poster.webp"}},"8":{"ours":{"src":"assets/h3-selected-20261001/new-035-8-ours.mp4","poster":"assets/h3-selected-20261001/new-035-8-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-035-8-baseline.mp4","poster":"assets/h3-selected-20261001/new-035-8-baseline-poster.webp"}}}},{"id":"t2va-h3wave03-l06","code":"A24","title":"Surreal vehicle desert","prompt":"integrated_multimodal_description: [Shot 1] A single compact vintage yellow submarine travels through a vast field of warm orange dunes as if dense sand were water. At the first frame, the upper hull, conning tower, and periscope move just beneath the dune surface, creating one coherent rolling sand wake. Wind-carved ridges, black rocks, dry grass, distant mesas, and a pale sky define the desert. The submarine dives fully under one dune, its wake crossing the slope, then breaches through the next ridge in one smooth rising motion. Sand sheets from the intact hull while the propeller and fins remain coherent. The camera tracks beside the moving wake, then pulls wide as the submarine settles half above the sand with a long curved trail behind it. No ocean, crew, extra vehicle, explosion, or flying sandstorm.\noverall_soundscape: Desert wind, deep engine hum under sand, granular rushing wake, hull emerging, sand sliding from metal, and one low sonar-like tone.\nnon_diegetic_music: Low rhythmic brass and percussion growing toward the breach.","width":900,"height":514,"steps":{"4":{"ours":{"src":"assets/feature-overviews/t2va-h3wave03-l06-ours-4.mp4","poster":"assets/feature-overviews/t2va-h3wave03-l06-ours-4-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave03-l06-dmd-4.mp4","poster":"assets/feature-overviews/t2va-h3wave03-l06-dmd-4-poster.webp"}},"8":{"ours":{"src":"assets/feature-overviews/t2va-h3wave03-l06-ours-8.mp4","poster":"assets/feature-overviews/t2va-h3wave03-l06-ours-8-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave03-l06-dmd-8.mp4","poster":"assets/feature-overviews/t2va-h3wave03-l06-dmd-8-poster.webp"}}}},{"id":"new-037","code":"A25","title":"Dragon and shield","prompt":"integrated_multimodal_description: [Shot 1] A 24mm lens in a fast, wide-range orbiting tracking shot follows an armored fighter on a ruined stone bridge as a dragon circles overhead, dives low, and strikes with its claws. The fighter raises a shield, slides backward, and recovers beside a broken parapet while sparks and dust cross the lens.\noverall_soundscape: Wing beats, stone grit, claw scrape, shield impact, armor strain, falling rubble, and wind over the gorge.\nnon_diegetic_music: Low brass and percussion with a sharp impact accent.","width":1344,"height":768,"steps":{"4":{"ours":{"src":"assets/h3-selected-20261001/new-037-4-ours.mp4","poster":"assets/h3-selected-20261001/new-037-4-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-037-4-baseline.mp4","poster":"assets/h3-selected-20261001/new-037-4-baseline-poster.webp"}},"8":{"ours":{"src":"assets/h3-selected-20261001/new-037-8-ours.mp4","poster":"assets/h3-selected-20261001/new-037-8-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-037-8-baseline.mp4","poster":"assets/h3-selected-20261001/new-037-8-baseline-poster.webp"}}}},{"id":"t2va-h3wave03-l08","code":"A26","title":"Animal food interaction","prompt":"integrated_multimodal_description: [Shot 1] A single sun bear stands on a broad jungle cliff ledge beside one enormous natural honeycomb attached beneath an overhanging rock. The bear, honeycomb cells, both front paws, face, and safe ledge are clear in the opening frame. Dense green canopy, vines, black rock, warm shafts of light, a distant waterfall, and a few bees kept far from the face create a rich environment. The bear climbs one low step, braces with one paw, and pulls a single thick slab of honeycomb free with the other. A slow golden ribbon of honey stretches from the hive, then breaks and pours over the slab while the bear sits back securely. The camera arcs from the bear's side toward a frontal three-quarter view, ending with the face, honey slab, and glowing stream visible. No swarm attack, fall, extra bear, or collapsing hive.\noverall_soundscape: Jungle ambience, claws on rock, wax comb tearing, thick honey stretching and dripping, bear breaths, and distant waterfall.\nnon_diegetic_music: Warm bass clarinet and light percussion with a playful final note.","width":900,"height":514,"steps":{"4":{"ours":{"src":"assets/feature-overviews/t2va-h3wave03-l08-ours-4.mp4","poster":"assets/feature-overviews/t2va-h3wave03-l08-ours-4-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave03-l08-dmd-4.mp4","poster":"assets/feature-overviews/t2va-h3wave03-l08-dmd-4-poster.webp"}},"8":{"ours":{"src":"assets/feature-overviews/t2va-h3wave03-l08-ours-8.mp4","poster":"assets/feature-overviews/t2va-h3wave03-l08-ours-8-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave03-l08-dmd-8.mp4","poster":"assets/feature-overviews/t2va-h3wave03-l08-dmd-8-poster.webp"}}}},{"id":"new-049","code":"A27","title":"Horse to bird","prompt":"integrated_multimodal_description: [Shot 1] A rider gallops across an open field on horseback. The camera uses a 35mm lens and makes a fast lateral track over a wide range parallel to the rider, holding the body at center as the horse seamlessly transforms into a giant bird during one stride. The rider's posture and forward motion remain continuous; the camera rises with the new wings as the bird carries the rider into a brief low flight without a cut. overall_soundscape: Hoofbeats, field wind, leather and tack movement, a rush of transforming feathers, and broad wingbeats are diegetic. non_diegetic_music: No music; make the impossible transformation legible through continuous motion and natural sound.","width":1344,"height":768,"steps":{"4":{"ours":{"src":"assets/h3-selected-20261001/new-049-4-ours.mp4","poster":"assets/h3-selected-20261001/new-049-4-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-049-4-baseline.mp4","poster":"assets/h3-selected-20261001/new-049-4-baseline-poster.webp"}},"8":{"ours":{"src":"assets/h3-selected-20261001/new-049-8-ours.mp4","poster":"assets/h3-selected-20261001/new-049-8-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-049-8-baseline.mp4","poster":"assets/h3-selected-20261001/new-049-8-baseline-poster.webp"}}}},{"id":"t2va-h3wave03-p01","code":"A28","title":"Portrait vehicle launch","prompt":"integrated_multimodal_description: [Shot 1] A 9:16 vertical cinematic view from the floor of a narrow red-rock canyon. One compact silver research rocket stands upright on a simple launch platform, fully visible from engine bells to pointed nose. Cables, service arms, canyon walls, sparse desert plants, safety lights without text, and a strip of blue sky create a tall layered frame; no people appear. Vapor vents once, the engine ignites with a stable white-orange plume, and the rocket rises vertically from the platform. The camera cranes upward at a safe side angle, following as the rocket passes between the canyon walls and enters the open sky. Dust expands across the canyon floor but remains below. The final frame shows the intact rocket high above the rim with one straight plume and the empty platform far below. No explosion, booster separation, or second rocket.\noverall_soundscape: Canyon wind, venting vapor, ignition rumble, sustained engine roar, platform vibration, dust, and fading echoes.\nnon_diegetic_music: A slow orchestral build overtaken by the engine at lift-off.","width":768,"height":1344,"steps":{"4":{"ours":{"src":"assets/feature-overviews/t2va-h3wave03-p01-ours-4.mp4","poster":"assets/feature-overviews/t2va-h3wave03-p01-ours-4-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave03-p01-dmd-4.mp4","poster":"assets/feature-overviews/t2va-h3wave03-p01-dmd-4-poster.webp"}},"8":{"ours":{"src":"assets/feature-overviews/t2va-h3wave03-p01-ours-8.mp4","poster":"assets/feature-overviews/t2va-h3wave03-p01-ours-8-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave03-p01-dmd-8.mp4","poster":"assets/feature-overviews/t2va-h3wave03-p01-dmd-8-poster.webp"}}}},{"id":"new-051","code":"A29","title":"Redwood cycling","prompt":"integrated_multimodal_description: [Shot 1] The camera tracks quickly from near range. A 24mm camera follows at a fast, controlled pace from close rear-wheel range as a mountain biker descends a forest trail beneath tall redwoods. Slide to the rider’s side through the ferns, move ahead into medium range, make a smooth partial orbit through a banked turn, and rise to a wide view of the winding trail with the biker continuing below.\noverall_soundscape: Knobby tires on dirt, chain rattle, wind through redwoods, and crushed fern sounds.\nnon_diegetic_music: None.","width":1344,"height":768,"steps":{"4":{"ours":{"src":"assets/h3-selected-20261001/new-051-4-ours.mp4","poster":"assets/h3-selected-20261001/new-051-4-ours-poster.webp"},"baseline":{"src":"assets/h3-selected-20261001/new-051-4-baseline.mp4","poster":"assets/h3-selected-20261001/new-051-4-baseline-poster.webp"}},"8":{"ours":{"src":"assets/av/case51-ours.mp4","poster":"assets/h3-selected-20261001/new-051-8-ours-poster.webp"},"baseline":{"src":"assets/av/case51-dmd.mp4","poster":"assets/h3-selected-20261001/new-051-8-baseline-poster.webp"}}}},{"id":"t2va-h3wave03-p02","code":"A30","title":"Portrait ice slide animal","prompt":"integrated_multimodal_description: [Shot 1] A 9:16 vertical polar scene built around one emperor penguin belly-sliding down a natural blue ice chute. The same complete penguin is visible from the first frame at the upper opening, with black back, white belly, yellow neck patches, short beak, two flippers, and two feet clearly established. The chute remains above water for the entire descent and curves gently between tall translucent ice walls. Snow shelves, trapped bubbles, blue fractures, icicles, distant mountains, and a small shallow pool at the bottom fill the portrait frame. The penguin leans forward, drops onto its belly, and slides along one clear continuous path, steering with both flippers while keeping its head and body shape stable. The camera descends beside the chute at the same speed. At the bottom, the penguin enters the shallow pool with one compact splash, immediately surfaces upright, and remains visibly the same emperor penguin. No underwater deep dive, fish, shark, second penguin, or collapsing ice.\noverall_soundscape: Polar wind, belly sliding over smooth ice, flippers brushing the chute, one compact splash, water settling, and a short penguin call.\nnon_diegetic_music: A playful descending woodwind phrase resolving with one soft cymbal at the splash.","width":768,"height":1344,"steps":{"4":{"ours":{"src":"assets/feature-overviews/t2va-h3wave03-p02-ours-4.mp4","poster":"assets/feature-overviews/t2va-h3wave03-p02-ours-4-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave03-p02-dmd-4.mp4","poster":"assets/feature-overviews/t2va-h3wave03-p02-dmd-4-poster.webp"}},"8":{"ours":{"src":"assets/feature-overviews/t2va-h3wave03-p02-ours-8.mp4","poster":"assets/feature-overviews/t2va-h3wave03-p02-ours-8-poster.webp"},"baseline":{"src":"assets/feature-overviews/t2va-h3wave03-p02-dmd-8.mp4","poster":"assets/feature-overviews/t2va-h3wave03-p02-dmd-8-poster.webp"}}}}];
